/** Whether a Transaction's money comes into (`income`) or goes out of (`expense`) its Wallet (epic: Kind). */
export type TransactionKind = 'income' | 'expense';

/**
 * One recorded flow of money into or out of a single Wallet, on a calendar date (epic: Shared Domain Entities →
 * Transaction). Not here yet: `recordedByUserId` (F-4) and `categoryId` (F-8).
 */
export interface Transaction {
  /** UUID, generated by Postgres. */
  id: string;
  walletId: string;
  kind: TransactionKind;
  /** Always > 0, in minor units of the Wallet's Currency; the Kind decides whether it adds to or takes from the Balance. */
  amountMinor: bigint;
  /** A calendar date `YYYY-MM-DD` — never a timestamp, never a JS Date (AD-1). */
  occurredOn: string;
  note: string | null;
  createdAt: Date;
  updatedAt: Date;
}

/** What Ledger needs to store a Transaction; the id and timestamps are generated by Postgres. */
export interface NewTransaction {
  walletId: string;
  kind: TransactionKind;
  amountMinor: bigint;
  occurredOn: string;
  note: string | null;
}
